class WalletRepositoryImpl implements WalletRepository {
  final WalletRemoteDataSource remoteDataSource;
  final WalletLocalDataSource localDataSource;
  final NetworkInfo networkInfo;

  @override
  Future<Either<Failure, WalletEntity>> getWallet() async {
    if (await networkInfo.isConnected) {
      try {
        final remote = await remoteDataSource.fetchWallet();
        await localDataSource.cacheWallet(remote);
        return Right(remote);
      } on ServerException catch (e) {
        return Left(ServerFailure(e.message));
      }
    } else {
      try {
        return Right(await localDataSource.getCachedWallet());
      } on CacheException {
        return Left(CacheFailure('No offline wallet cached'));
      }
    }
  }
}

