class TransferNotifier extends ChangeNotifier {
  final PaymentService _service;
  bool isLoading = false;
  TransferNotifier(this._service);

  Future<void> pay(TransferParams params) async {
    isLoading = true;
    notifyListeners();
    await _service.process(params);
    // User popped screen while payment was in-flight
    isLoading = false;
    notifyListeners(); // Throws FlutterError
  }
}

test('should call executeTransfer on repository with correct params', () async {
  when(() => mockRepository.executeTransfer(params))
      .thenAnswer((_) async => Right(receipt));

  final result = await useCase(params);

  expect(result, Right(receipt));
  verify(() => mockRepository.executeTransfer(params)).called(1);
  verifyNoMoreInteractions(mockRepository);
});

test('WalletNotifier sets loading and emits balance on success', () async {
  final mockRepo = MockWalletRepository();
  when(() => mockRepo.getBalance()).thenAnswer((_) async => Right(WalletEntity(balanceInBaisa: 5000)));

  final notifier = WalletNotifier(mockRepo);
  final states = <bool>[];
  notifier.addListener(() => states.add(notifier.isLoading));

  await notifier.fetchBalance();

  expect(states, [true, false]);
  expect(notifier.balance, 5000);
});

